<?php require_once __DIR__ . '/../includes/config.php'; require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/layout.php'; require_login();
$date=$_POST['attendance_date']??($_GET['attendance_date']??date('Y-m-d'));
$routes=array_map('trim',explode(',',(string)$pdo->query("SELECT setting_value FROM settings WHERE setting_key='routes'")->fetchColumn()));
$statuses=array_map('trim',explode(',',(string)$pdo->query("SELECT setting_value FROM settings WHERE setting_key='attendance_statuses'")->fetchColumn()));
$route=$_POST['route']??($_GET['route']??($routes[0]??'arriving')); $busFilter=(int)($_POST['bus_id']??($_GET['bus_id']??0)); $studentIds=array_map('intval',$_POST['student_ids']??($_GET['student_ids']??[]));
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['status'])){ foreach($_POST['status'] as $id=>$st){ $pdo->prepare('REPLACE INTO attendance (attendance_date,student_id,route,status) VALUES (?,?,?,?)')->execute([$date,(int)$id,$route,$st]); }}
$buses=$pdo->query('SELECT id,name FROM buses ORDER BY name')->fetchAll(); $allStudents=$pdo->query('SELECT id,code,name FROM students ORDER BY name')->fetchAll();
$params=[]; $where=[]; if($busFilter>0){$where[]='s.bus_id=?';$params[]=$busFilter;} if($studentIds){ $where[]='s.id IN ('.implode(',',array_fill(0,count($studentIds),'?')).')'; $params=array_merge($params,$studentIds); }
$sql='SELECT s.id,s.code,s.name,c.name class_name,b.name bus_name FROM students s LEFT JOIN classes c ON c.id=s.class_id LEFT JOIN buses b ON b.id=s.bus_id'; if($where)$sql.=' WHERE '.implode(' AND ',$where); $sql.=' ORDER BY c.name,s.name';
$st=$pdo->prepare($sql);$st->execute($params);$students=$st->fetchAll();
$ex=[];$s=$pdo->prepare('SELECT student_id,status FROM attendance WHERE attendance_date=? AND route=?');$s->execute([$date,$route]);foreach($s->fetchAll() as $r)$ex[$r['student_id']]=$r['status']; ui_start('Attendance');?>
<div class="card"><h2>Attendance</h2><form method="get"><div class="grid"><div><label>Attendance Date</label><input type="date" name="attendance_date" value="<?=h($date)?>"></div><div><label>Route</label><select name="route"><?php foreach($routes as $r):?><option <?=$route===$r?'selected':''?>><?=h($r)?></option><?php endforeach;?></select></div><div><label>Bus Filter</label><select name="bus_id"><option value="0">All buses</option><?php foreach($buses as $b):?><option value="<?=$b['id']?>" <?=$busFilter===$b['id']?'selected':''?>><?=h($b['name'])?></option><?php endforeach;?></select></div><div><label>Students</label><div id="att-student-ms"></div></div><button class="btn">Filter</button></div></form><form method="post"><input type="hidden" name="attendance_date" value="<?=h($date)?>"><input type="hidden" name="route" value="<?=h($route)?>"><input type="hidden" name="bus_id" value="<?=$busFilter?>"><?php foreach($studentIds as $sid):?><input type="hidden" name="student_ids[]" value="<?=$sid?>"><?php endforeach;?><table><tr><th>Code</th><th>Name</th><th>Class</th><th>Bus</th><th>Status</th></tr><?php foreach($students as $s):$cur=$ex[$s['id']]??($statuses[0]??'attending');?><tr><td><?=h($s['code'])?></td><td><?=h($s['name'])?></td><td><?=h($s['class_name'])?></td><td><?=h($s['bus_name']??'No bus')?></td><td><select name="status[<?=$s['id']?>]"><?php foreach($statuses as $o):?><option <?=$o===$cur?'selected':''?>><?=h($o)?></option><?php endforeach;?></select></td></tr><?php endforeach;?></table><button class="btn">Save Attendance</button></form></div>
<script>
function mountMS(elId, items, pre=[]){const host=document.getElementById(elId);host.innerHTML='<input type="text" class="ms-in" placeholder="Type student name..."><div class="ms-dd"></div><div class="ms-tags"></div>';const input=host.querySelector('.ms-in'),dd=host.querySelector('.ms-dd'),tags=host.querySelector('.ms-tags');let selected=[...pre];function render(){tags.innerHTML='';selected.forEach(id=>{const it=items.find(x=>x.id==id);if(!it)return;const t=document.createElement('span');t.className='tag';t.textContent=it.label+' ×';t.onclick=()=>{selected=selected.filter(s=>s!=id);sync();};tags.appendChild(t);});host.querySelectorAll('input[name="student_ids[]"]').forEach(n=>n.remove());selected.forEach(id=>{const h=document.createElement('input');h.type='hidden';h.name='student_ids[]';h.value=id;host.appendChild(h);});}
input.oninput=()=>{const q=input.value.toLowerCase();dd.innerHTML='';items.filter(i=>i.label.toLowerCase().includes(q)&&!selected.includes(i.id)).slice(0,8).forEach(i=>{const o=document.createElement('div');o.className='ms-opt';o.textContent=i.label;o.onclick=()=>{selected.push(i.id);input.value='';dd.innerHTML='';sync();};dd.appendChild(o);});}; function sync(){render();} sync();}
mountMS('att-student-ms', <?=json_encode(array_map(fn($s)=>['id'=>(int)$s['id'],'label'=>$s['code'].' - '.$s['name']],$allStudents))?>, <?=json_encode($studentIds)?>);
</script>
<?php ui_end(); ?>
